SELECT CASE WHEN YEAR(s.started_at) < 2024 THEN 'before_2024' WHEN YEAR(s.started_at) = 2024 THEN '2024' ELSE 'after_2024' END AS started_cohort, MAX(we.duration_sec) AS max_duration_sec, AVG(we.duration_sec) AS avg_duration_sec FROM web_events we FULL OUTER JOIN sessions s ON we.session_id = s.id WHERE s.browser = 'Edge' GROUP BY CASE WHEN YEAR(s.started_at) < 2024 THEN 'before_2024' WHEN YEAR(s.started_at) = 2024 THEN '2024' ELSE 'after_2024' END ORDER BY avg_duration_sec DESC
